#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int *parent;
    int *rank;
    int size;
} UnionFind;

UnionFind* ufCreate(int n) {
    UnionFind *uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->rank = (int*)calloc(n, sizeof(int));
    uf->size = n;
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
    }
    return uf;
}

int ufFind(UnionFind *uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = ufFind(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

bool ufUnion(UnionFind *uf, int x, int y) {
    int rx = ufFind(uf, x);
    int ry = ufFind(uf, y);
    if (rx == ry) return false;
    if (uf->rank[rx] < uf->rank[ry]) {
        uf->parent[rx] = ry;
    } else if (uf->rank[ry] < uf->rank[rx]) {
        uf->parent[ry] = rx;
    } else {
        uf->parent[ry] = rx;
        uf->rank[rx]++;
    }
    return true;
}

void ufFree(UnionFind *uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

/**
 * Note: The returned array must be malloced, assume caller calls free().
 */
bool* friendRequests(int n, int** restrictions, int restrictionsSize, int* restrictionsColSize,
                     int** requests, int requestsSize, int* requestsColSize, int* returnSize){
    *returnSize = requestsSize;
    bool *res = (bool*)malloc(requestsSize * sizeof(bool));
    UnionFind *uf = ufCreate(n);

    for (int i = 0; i < requestsSize; i++) {
        int u = requests[i][0];
        int v = requests[i][1];
        int ru = ufFind(uf, u);
        int rv = ufFind(uf, v);

        if (ru == rv) {
            // Already friends (direct or indirect)
            res[i] = true;
            continue;
        }

        // Check restrictions: no pair in restrictions should be in the same set after union
        bool canUnion = true;
        for (int j = 0; j < restrictionsSize; j++) {
            int x = restrictions[j][0];
            int y = restrictions[j][1];
            int rx = ufFind(uf, x);
            int ry = ufFind(uf, y);

            // If after union ru and rv would be same set, check if restriction violated
            // The union would merge ru and rv sets, so if (rx == ru and ry == rv) or (rx == rv and ry == ru),
            // then restriction violated.
            if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                canUnion = false;
                break;
            }
        }

        if (canUnion) {
            ufUnion(uf, u, v);
            res[i] = true;
        } else {
            res[i] = false;
        }
    }

    ufFree(uf);
    return res;
}

